// Run at configure time (see dependencies.cmake) against the system's FFmpeg: it only qualifies when it is LGPL and has the
// demuxers (DEMUXERS, a comma separated list) and decoders (DECODERS) that the runtime plays movies with. Prints why not.
#include <libavcodec/avcodec.h>
#include <libavformat/avformat.h>
#include <libavutil/avutil.h>
#include <stdio.h>
#include <string.h>

static int each(const char* list, int (*check)(const char*))
{
	char buffer[2048];
	strncpy(buffer, list, sizeof(buffer) - 1);
	buffer[sizeof(buffer) - 1] = 0;
	int missing = 0;
	for (char* name = strtok(buffer, ","); name; name = strtok(NULL, ",")) {
		if (!check(name)) {
			printf("missing %s\n", name);
			missing++;
		}
	}
	return missing;
}

static int has_decoder(const char* name)
{
	return avcodec_find_decoder_by_name(name) != NULL;
}

static int has_demuxer(const char* name)
{
	return av_find_input_format(name) != NULL;
}

int main(void)
{
	// "LGPL version 2.1 or later" for LGPL builds, "GPL version 2 or later" for the builds with GPL parts (the ones of Debian and Ubuntu).
	const char* license = avcodec_license();
	if (strncmp(license, "LGPL", 4) != 0) {
		printf("licensed as '%s', not LGPL\n", license);
		return 1;
	}
	return each(DEMUXERS, has_demuxer) + each(DECODERS, has_decoder) ? 2 : 0;
}
